html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Own your operating model, rent your tools · Aggie Innovators</title><style>'+css+'</style></head><body><main id="stage"><img class="logo" src="assets/digital-meld-logo.png" alt="Digital Meld">'
for i,s in enumerate(slides):html+=f'<section id="slide{i+1}" class="slide {s["cls"]}" aria-label="Slide {i+1}: {e(s["title"].replace("<br>"," ").replace("<em>","").replace("</em>",""))}" data-title="{e(s["title"])}"><div class="kicker">{s["kicker"]}</div><h1>{s["title"]}</h1>{s["body"]}</section>'
html+='''<nav class="controls" aria-label="Presentation controls"><button id="prev" aria-label="Previous slide">←</button><button id="next" aria-label="Next slide">→</button><button id="theme-toggle" aria-label="Switch to light mode" title="Switch to light mode"><svg class="theme-sun" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4.2 4.2l2.1 2.1m11.4 11.4 2.1 2.1M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1"/></svg><svg class="theme-moon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20.5 14A8.5 8.5 0 0 1 10 3.5 8.5 8.5 0 1 0 20.5 14Z"/></svg></button><button id="fullscreen" aria-label="Enter fullscreen" title="Fullscreen"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button></nav><footer class="footer"><span>Digital Meld / Aggie Innovators</span><span id="counter"></span></footer><div class="progress" id="progress"></div></main><script>'''

html+='''const slides=[...document.querySelectorAll('.slide')];let current=0;const $=id=>document.getElementById(id);const themeKey='aggie-slides-theme';const systemTheme=matchMedia('(prefers-color-scheme: light)');let savedTheme;try{savedTheme=localStorage.getItem(themeKey)}catch{}function setTheme(theme,persist=false){document.documentElement.dataset.theme=theme;const label=theme==='dark'?'Switch to light mode':'Switch to dark mode';$('theme-toggle').setAttribute('aria-label',label);$('theme-toggle').title=label;if(persist){savedTheme=theme;try{localStorage.setItem(themeKey,theme)}catch{}}}setTheme(['light','dark'].includes(savedTheme)?savedTheme:(systemTheme.matches?'light':'dark'));$('theme-toggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);systemTheme.addEventListener('change',()=>{if(!['light','dark'].includes(savedTheme))setTheme(systemTheme.matches?'light':'dark')});function scale(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1600,innerHeight/900))}function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>{s.classList.toggle('active',j===current);s.setAttribute('aria-hidden',j!==current)});$('counter').textContent=`${current+1} / ${slides.length}`;$('progress').style.width=`${(current+1)/slides.length*100}%`;history.replaceState(null,'',`#slide${current+1}`)}function fromHash(){const match=location.hash.match(/^#slide(\\d+)$/);show(match?Number(match[1])-1:0)}$('prev').onclick=()=>show(current-1);$('next').onclick=()=>show(current+1);$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>{})};addEventListener('keydown',ev=>{if(ev.target.closest('button,a,input,textarea'))return;if(['ArrowRight','PageDown',' '].includes(ev.key)){ev.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(ev.key)){ev.preventDefault();show(current-1)}if(ev.key==='Home')show(0);if(ev.key==='End')show(slides.length-1);});addEventListener('resize',scale);addEventListener('hashchange',fromHash);if(new URLSearchParams(location.search).has('export'))document.body.classList.add('export');scale();fromHash();</script></body></html>'''
(p/'slides.html').write_text(html)
(p/'speaker-notes.md').write_text('# Speaker notes: 90 minutes\n\nSeparate facilitator reference; not displayed in the deck. Times are elapsed from the beginning of the presentation.\n\n'+'\n\n'.join(f'## {i+1}. '+s['title'].replace('<br>',' ').replace('<em>','').replace('</em>','')+'\n\n'+s['notes'] for i,s in enumerate(slides))+'\n')
